local required = {"makefolder", "isfolder", "writefile"}
for _, name in ipairs(required) do
    if type(getfenv()[name]) ~= "function" then
        error("Executor filesystem API missing: " .. name)
    end
end

local folders = {
    "unnamed",
    "unnamed/core",
    "unnamed/rivals",
    "unnamed/rivals/cache",
    "unnamed/rivals/chat",
    "unnamed/rivals/fonts",
    "unnamed/rivals/images",
    "unnamed/rivals/lua",
    "unnamed/rivals/lua/configs",
    "unnamed/rivals/lua/scripts",
    "unnamed/rivals/settings",
    "unnamed/rivals/sounds",
    "unnamed/rivals/themes",
    "unnamed/themes",
    "unnamed/themes/themes",
}

local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local lookup = {}
for i = 1, #alphabet do
    lookup[string.byte(alphabet, i)] = i - 1
end

local function decode(data)
    data = string.gsub(data, "%s", "")
    local result = {}
    if #data % 4 ~= 0 then
        error("Invalid Base64 length")
    end
    for i = 1, #data, 4 do
        local a, b, c, d = string.byte(data, i, i + 3)
        local x, y = lookup[a], lookup[b]
        local z, w = (c == 61 and 0 or lookup[c]), (d == 61 and 0 or lookup[d])
        if not x or not y or z == nil or w == nil then
            error("Invalid Base64 data")
        end
        local n = x * 262144 + y * 4096 + z * 64 + w
        if c == 61 then
            result[#result + 1] = string.char(math.floor(n / 65536))
        elseif d == 61 then
            result[#result + 1] = string.char(math.floor(n / 65536), math.floor(n / 256) % 256)
        else
            result[#result + 1] = string.char(math.floor(n / 65536), math.floor(n / 256) % 256, n % 256)
        end
    end
    return table.concat(result)
end

