for _, folder in ipairs(folders) do
    if not isfolder(folder) then
        makefolder(folder)
    end
end

local total = 0
for _, item in ipairs(files) do
    local contents = decode(item.data)
    assert(#contents == item.size, "Size mismatch: " .. item.path)
    writefile(item.path, contents)
    total = total + 1
    print("[RESTORE] " .. item.path .. " (" .. item.size .. " bytes)")
end
print("[RESTORE] Finished: " .. #folders .. " directories, " .. total .. " files")
